// Aurora Mail website (auto-generated from web.html — DO NOT EDIT)
export default "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#0b0b10\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n<title>Aurora Mail</title>\n<style>\n:root{\n  --bg:#0b0b10; --surface:#14141b; --surface-2:#1c1c26; --surface-3:#262634;\n  --line:#2a2a3a; --text:#f2f2f7; --muted:#9a9aae; --faint:#5e5e74;\n  --accent:#7c5cff; --accent-2:#9d86ff; --gold:#f0b429;\n  --danger:#ff5c6c; --ok:#37d67a; --info:#4aa8ff;\n  --radius:14px; --safe-t:env(safe-area-inset-top,0px); --safe-b:env(safe-area-inset-bottom,0px);\n  --sidebar:264px;\n}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml,body{height:100%}\nbody{\n  background:var(--bg);color:var(--text);\n  font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,\"Helvetica Neue\",Arial,sans-serif;\n  font-size:15px;line-height:1.5;-webkit-font-smoothing:antialiased;overflow:hidden;\n}\nbutton{font:inherit;color:inherit;background:none;border:0;cursor:pointer}\ninput{font:inherit;color:inherit}\n::-webkit-scrollbar{width:9px;height:9px}\n::-webkit-scrollbar-thumb{background:var(--surface-3);border-radius:9px}\n::-webkit-scrollbar-track{background:transparent}\n\n/* ============ LAYOUT ============ */\n#app{height:100%;display:flex}\n/* sidebar */\n#sidebar{\n  width:var(--sidebar);flex:none;display:flex;flex-direction:column;\n  background:linear-gradient(180deg,#111119,#0c0c12);\n  border-right:1px solid var(--line);min-height:0;\n}\n.brand{display:flex;align-items:center;gap:11px;padding:18px 18px 14px}\n.brand .logo{width:38px;height:38px;border-radius:12px;flex:none;\n  background:linear-gradient(135deg,var(--accent),#4a2fd6);\n  display:grid;place-items:center;font-size:19px;box-shadow:0 6px 18px rgba(124,92,255,.35)}\n.brand h1{font-size:17px;font-weight:800;letter-spacing:.2px}\n.brand small{display:block;font-size:11px;color:var(--faint);font-weight:600;letter-spacing:.6px;text-transform:uppercase}\n.side-scroll{flex:1;overflow-y:auto;padding:6px 10px calc(16px + var(--safe-b))}\n.side-label{font-size:10.5px;font-weight:800;letter-spacing:1.2px;text-transform:uppercase;color:var(--faint);padding:14px 10px 7px}\n.addr{display:flex;align-items:center;gap:10px;padding:10px 11px;border-radius:12px;cursor:pointer;width:100%;text-align:left;transition:background .14s}\n.addr:hover{background:var(--surface-2)}\n.addr.on{background:rgba(124,92,255,.16);box-shadow:inset 0 0 0 1px rgba(124,92,255,.4)}\n.addr .dot{width:8px;height:8px;border-radius:99px;background:var(--ok);flex:none}\n.addr .dot.off{background:var(--faint)}\n.addr .nm{flex:1;min-width:0}\n.addr .nm b{display:block;font-size:13.5px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;direction:ltr;text-align:left}\n.addr .nm span{font-size:11.5px;color:var(--muted)}\n.addr .ct{font-size:10.5px;font-weight:700;color:var(--faint);background:var(--surface-2);border-radius:99px;padding:2px 7px;flex:none}\n.side-actions{padding:10px;border-top:1px solid var(--line);display:grid;gap:7px}\n.btn{display:flex;align-items:center;justify-content:center;gap:8px;padding:11px 14px;border-radius:12px;\n  font-size:13.5px;font-weight:700;transition:transform .1s,background .14s}\n.btn:active{transform:scale(.97)}\n.btn.primary{background:linear-gradient(135deg,var(--accent),#5b34e0);color:#fff;box-shadow:0 4px 14px rgba(124,92,255,.3)}\n.btn.ghost{background:var(--surface-2);color:var(--text)}\n.btn.danger{background:rgba(255,92,108,.14);color:var(--danger)}\n.btn.sm{padding:7px 12px;font-size:12.5px;border-radius:10px}\n.btn:disabled{opacity:.45;pointer-events:none}\n\n/* main */\n#main{flex:1;display:flex;flex-direction:column;min-width:0;min-height:0}\n#topbar{display:flex;align-items:center;gap:12px;padding:calc(12px + var(--safe-t)) 16px 12px;border-bottom:1px solid var(--line);background:rgba(11,11,16,.86);backdrop-filter:blur(12px)}\n#topbar .tb-title{font-weight:800;font-size:16px;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.icon-btn{width:36px;height:36px;border-radius:11px;display:grid;place-items:center;background:var(--surface-2);flex:none;transition:background .14s}\n.icon-btn:hover{background:var(--surface-3)}\n.icon-btn svg{width:18px;height:18px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n#search-wrap{padding:10px 16px 4px}\n#search{width:100%;padding:10px 14px 10px 38px;border-radius:12px;background:var(--surface);\n  border:1px solid var(--line);outline:none;font-size:14px;transition:border-color .15s}\n#search:focus{border-color:var(--accent)}\n.search-rel{position:relative}\n.search-rel svg{position:absolute;left:12px;top:50%;transform:translateY(-50%);width:16px;height:16px;stroke:var(--faint);fill:none;stroke-width:2}\n#list-scroll{flex:1;overflow-y:auto;padding:8px 10px calc(24px + var(--safe-b))}\n.mail{display:flex;gap:11px;padding:12px;border-radius:var(--radius);cursor:pointer;margin-bottom:5px;\n  border:1px solid transparent;transition:background .14s,border-color .14s;position:relative}\n.mail:hover{background:var(--surface)}\n.mail.on{background:var(--surface-2);border-color:rgba(124,92,255,.45)}\n.mail.unread{background:linear-gradient(90deg,rgba(124,92,255,.10),rgba(124,92,255,0) 55%),var(--surface)}\n.mail.unread.on{background:linear-gradient(90deg,rgba(124,92,255,.16),rgba(124,92,255,.04) 55%),var(--surface-2)}\n.avatar{width:38px;height:38px;border-radius:12px;flex:none;display:grid;place-items:center;\n  font-weight:800;font-size:15px;color:#fff;letter-spacing:-.3px}\n.mail .who{flex:1;min-width:0}\n.mail .r1{display:flex;align-items:baseline;gap:8px}\n.mail .sender{font-weight:700;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}\n.mail.unread .sender{font-weight:800}\n.mail .time{font-size:11px;color:var(--faint);flex:none;font-weight:600}\n.mail .subj{font-size:13px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:2px}\n.mail.unread .subj{color:var(--text)}\n.mail .preview{font-size:12px;color:var(--faint);margin-top:3px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.45}\n.unread-dot{position:absolute;top:12px;right:12px;width:8px;height:8px;border-radius:99px;background:var(--accent)}\n.otp-chip{display:inline-flex;align-items:center;gap:5px;margin-top:6px;background:rgba(240,180,41,.13);\n  color:var(--gold);font-size:11.5px;font-weight:800;padding:3px 9px;border-radius:8px;letter-spacing:.4px}\n.otp-chip svg{width:12px;height:12px;stroke:currentColor;fill:none;stroke-width:2.4}\n\n/* empty / loading */\n.empty{padding:56px 26px;text-align:center;color:var(--muted)}\n.empty .ico{font-size:42px;margin-bottom:12px;opacity:.7}\n.empty h3{font-size:16px;font-weight:700;color:var(--text);margin-bottom:6px}\n.empty p{font-size:13.5px;line-height:1.65;max-width:330px;margin:0 auto}\n.spin{width:26px;height:26px;border:2.5px solid var(--surface-3);border-top-color:var(--accent);\n  border-radius:50%;animation:sp .7s linear infinite;margin:44px auto}\n@keyframes sp{to{transform:rotate(360deg)}}\n\n/* ============ TOAST ============ */\n#toast{position:fixed;bottom:calc(24px + var(--safe-b));left:50%;transform:translateX(-50%) translateY(16px);\n  background:var(--surface-3);color:var(--text);padding:11px 20px;border-radius:99px;font-size:13.5px;font-weight:700;\n  box-shadow:0 10px 30px rgba(0,0,0,.5);z-index:99;opacity:0;pointer-events:none;transition:all .22s;max-width:80vw;\n  text-align:center;border:1px solid var(--line)}\n#toast.show{opacity:1;transform:translateX(-50%) translateY(0)}\n\n/* ============ READER ============ */\n#reader{flex:1;display:flex;flex-direction:column;min-width:0;min-height:0;background:var(--bg)}\n#reader-head{display:flex;align-items:center;gap:10px;padding:calc(12px + var(--safe-t)) 14px 12px;border-bottom:1px solid var(--line)}\n#reader-head h2{flex:1;font-size:16px;font-weight:800;line-height:1.35;min-width:0}\n.reader-meta{padding:12px 16px 4px;font-size:12.5px;color:var(--muted);line-height:1.75;border-bottom:1px solid var(--line)}\n.reader-meta b{color:var(--text);font-weight:700}\n.reader-meta .from-line{display:flex;align-items:center;gap:9px;margin-bottom:2px}\n.reader-meta .from-line .avatar{width:32px;height:32px;border-radius:10px;font-size:13px}\n#reader-scroll{flex:1;overflow-y:auto;padding:14px 16px calc(30px + var(--safe-b))}\n#reader-body{font-size:14.5px;line-height:1.75;color:var(--text);white-space:pre-wrap;word-break:break-word;overflow-wrap:anywhere}\n#reader-body a{color:var(--info);word-break:break-all}\n.html-mail{border:0;width:100%;min-height:200px;border-radius:10px;background:#fff}\n.reader-nav{display:flex;gap:8px;padding:10px 14px calc(10px + var(--safe-b));border-top:1px solid var(--line);background:var(--surface)}\n.reader-nav .btn{flex:1}\n.otp-big{display:flex;align-items:center;gap:12px;background:rgba(240,180,41,.1);border:1px dashed rgba(240,180,41,.4);\n  border-radius:14px;padding:14px 16px;margin-bottom:14px}\n.otp-big code{font-size:26px;font-weight:800;letter-spacing:5px;color:var(--gold);flex:1}\n\n/* ============ MOBILE ============ */\n#mobile-bar{display:none}\n@media (max-width:860px){\n  #sidebar{position:fixed;left:0;top:0;bottom:0;z-index:60;transform:translateX(-105%);\n    transition:transform .26s cubic-bezier(.4,0,.2,1);box-shadow:14px 0 40px rgba(0,0,0,.5);width:min(var(--sidebar),82vw)}\n  body.side-open #sidebar{transform:none}\n  #side-scrim{position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:55;opacity:0;pointer-events:none;transition:opacity .2s}\n  body.side-open #side-scrim{opacity:1;pointer-events:auto}\n  #mobile-bar{display:flex;align-items:center;gap:12px;padding:calc(12px + var(--safe-t)) 12px 10px}\n  #reader-head{padding-top:8px}\n}\n@media (min-width:861px){ #reader{display:flex} }\n/* desktop: two-pane */\n@media (min-width:861px){\n  #pane{flex:1;display:flex;min-height:0}\n  #list-col{width:390px;flex:none;display:flex;flex-direction:column;border-right:1px solid var(--line);min-height:0}\n  #reader{flex:1}\n  body.no-reader #reader{display:none}\n}\n@media (max-width:860px){\n  #pane{flex:1;display:flex;min-height:0}\n  #list-col{flex:1;display:flex;flex-direction:column;min-height:0}\n  body.reader-open #list-col{display:none}\n  body:not(.reader-open) #reader{display:none}\n}\n</style>\n</head>\n<body>\n<div id=\"side-scrim\"></div>\n<div id=\"app\">\n  <!-- ============ SIDEBAR ============ -->\n  <aside id=\"sidebar\">\n    <div class=\"brand\">\n      <div class=\"logo\">🐴</div>\n      <div><h1>Aurora Mail</h1><small>Private Inbox</small></div>\n    </div>\n    <div class=\"side-scroll\">\n      <div class=\"side-label\">My Addresses</div>\n      <div id=\"addr-list\"><div class=\"spin\"></div></div>\n    </div>\n    <div class=\"side-actions\">\n      <button class=\"btn primary\" id=\"btn-new\">\n        <svg viewBox=\"0 0 24 24\" style=\"width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:2.4;stroke-linecap:round\"><path d=\"M12 5v14M5 12h14\"/></svg>\n        New Address\n      </button>\n      <button class=\"btn ghost\" id=\"btn-logout\">\n        <svg viewBox=\"0 0 24 24\" style=\"width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round\"><path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9\"/></svg>\n        Log out\n      </button>\n    </div>\n  </aside>\n\n  <!-- ============ MAIN ============ -->\n  <div id=\"main\">\n    <div id=\"mobile-bar\">\n      <button class=\"icon-btn\" id=\"btn-side\" aria-label=\"menu\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M3 6h18M3 12h18M3 18h18\"/></svg>\n      </button>\n      <div style=\"font-weight:800;font-size:16px;flex:1\">Aurora Mail</div>\n      <button class=\"icon-btn\" id=\"btn-new-m\" aria-label=\"new\">\n        <svg viewBox=\"0 0 24 24\"><path d=\"M12 5v14M5 12h14\"/></svg>\n      </button>\n    </div>\n\n    <div id=\"pane\">\n      <!-- list column -->\n      <div id=\"list-col\">\n        <div id=\"topbar\">\n          <button class=\"icon-btn\" id=\"btn-refresh\" aria-label=\"refresh\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M21 12a9 9 0 1 1-3-6.7L21 8\"/><path d=\"M21 3v5h-5\"/></svg>\n          </button>\n          <div class=\"tb-title\" id=\"tb-title\">Inbox</div>\n          <button class=\"icon-btn\" id=\"btn-side-d\" aria-label=\"addresses\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M4 4h16v16H4z\"/><path d=\"M9 9h6v6H9z\"/></svg>\n          </button>\n        </div>\n        <div id=\"search-wrap\">\n          <div class=\"search-rel\">\n            <svg viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"M21 21l-4.3-4.3\"/></svg>\n            <input id=\"search\" placeholder=\"Search inbox…\" autocomplete=\"off\" spellcheck=\"false\">\n          </div>\n        </div>\n        <div id=\"list-scroll\"><div class=\"spin\"></div></div>\n      </div>\n\n      <!-- reader -->\n      <div id=\"reader\">\n        <div id=\"reader-head\">\n          <button class=\"icon-btn\" id=\"btn-back\" aria-label=\"back\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M19 12H5M12 19l-7-7 7-7\"/></svg>\n          </button>\n          <h2 id=\"r-subj\">—</h2>\n          <button class=\"icon-btn\" id=\"btn-del\" aria-label=\"delete\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M3 6h18M8 6V4h8v2M6 6l1 14h10l1-14\"/></svg>\n          </button>\n        </div>\n        <div class=\"reader-meta\" id=\"r-meta\"></div>\n        <div id=\"reader-scroll\"><div id=\"reader-body\" class=\"empty\"><div class=\"ico\">✉️</div><p>Select an email to read it.</p></div></div>\n        <div class=\"reader-nav\">\n          <button class=\"btn ghost sm\" id=\"btn-prev\">← Prev</button>\n          <button class=\"btn ghost sm\" id=\"btn-next\">Next →</button>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n/* ==================== STATE ==================== */\nconst $ = s => document.querySelector(s);\nconst $$ = s => Array.from(document.querySelectorAll(s));\nconst state = {\n  addresses: [], active: null, mails: [], openIdx: -1, q: '',\n  user: { id: 0, name: '' }, domain: 'mesterio.life',\n};\n\n/* ==================== UTIL ==================== */\nfunction esc(s){ return String(s==null?'':s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])); }\nfunction avatarColor(s){\n  let h = 0; for (const ch of String(s||'?')) h = (h * 31 + ch.charCodeAt(0)) % 360;\n  return `hsl(${h} 62% 42%)`;\n}\nfunction initials(s){ const t = String(s||'?').replace(/<[^>]*>/g,'').trim(); return t.charAt(0).toUpperCase(); }\nfunction prettySender(s){\n  let t = String(s||'?');\n  const m = t.match(/^\"?([^\"<]+?)\"?\\s*</);\n  return m ? m[1].trim() : t.replace(/<[^>]*>/g,'').trim();\n}\nfunction fmtTime(ts){\n  const d = new Date(ts*1000), now = new Date();\n  const sameDay = d.toDateString() === now.toDateString();\n  const opts = sameDay ? {hour:'2-digit',minute:'2-digit'} : {month:'short',day:'numeric'};\n  return d.toLocaleString('en-GB', opts).replace(',', '');\n}\nfunction fmtFull(ts){ return new Date(ts*1000).toLocaleString('en-GB', {dateStyle:'medium', timeStyle:'short'}); }\nfunction toast(msg){\n  let t = $('#toast');\n  if (!t){ t = document.createElement('div'); t.id='toast'; document.body.appendChild(t); }\n  t.textContent = msg; t.classList.add('show');\n  clearTimeout(t._h); t._h = setTimeout(() => t.classList.remove('show'), 1900);\n}\nfunction copy(text, msg){\n  navigator.clipboard && navigator.clipboard.writeText(text).then(() => toast(msg || 'Copied')).catch(() => toast('Copy failed'));\n}\nfunction extractOtp(text){\n  if (!text) return null;\n  const t = String(text);\n  const pats = [\n    /\\b(\\d{6})\\b/, /\\b(\\d{4})\\b/, /code[:\\s]+([A-Z0-9]{4,8})/i,\n    /کد[:\\s]*([0-9]{4,8})/, /رمز[:\\s]*([0-9]{4,8})/,\n  ];\n  for (const p of pats){ const m = t.match(p); if (m) return m[1]; }\n  return null;\n}\n\n/* ==================== API ==================== */\nasync function api(path, opts){\n  const r = await fetch('/web/api' + path, Object.assign({ headers: { 'Content-Type': 'application/json' } }, opts || {}));\n  let d = null;\n  try { d = await r.json(); } catch {}\n  if (!r.ok) throw new Error((d && d.error) || ('HTTP ' + r.status));\n  return d;\n}\n\n/* ==================== SIDEBAR ==================== */\nasync function loadAddresses(){\n  const list = $('#addr-list');\n  try {\n    const d = await api('/addresses');\n    state.addresses = d.addresses || [];\n    state.active = d.active || (state.addresses[0] && state.addresses[0].address) || null;\n    state.domain = d.domain || state.domain;\n    state.user = d.user || state.user;\n    if (!state.addresses.length){\n      list.innerHTML = `<div class=\"empty\" style=\"padding:26px 10px\"><div class=\"ico\">📬</div>\n        <p>No addresses yet. Create your first inbox.</p></div>`;\n      return;\n    }\n    list.innerHTML = state.addresses.map(a => `\n      <button class=\"addr ${a.address===state.active?'on':''}\" data-addr=\"${esc(a.address)}\">\n        <span class=\"dot ${a.mail_count?'':'off'}\"></span>\n        <span class=\"nm\"><b>${esc(a.address)}</b><span>${a.mail_count||0} email${(a.mail_count||0)===1?'':'s'}</span></span>\n        <span class=\"ct\">${a.unread||0||''}</span>\n      </button>`).join('');\n    list.querySelectorAll('.addr').forEach(b => b.addEventListener('click', () => {\n      state.active = b.dataset.addr; closeSide(); loadAddresses().then(loadInbox);\n    }));\n  } catch (e){\n    list.innerHTML = `<div class=\"empty\"><div class=\"ico\">⚠️</div><p>${esc(e.message)}</p></div>`;\n  }\n}\n\n/* ==================== INBOX LIST ==================== */\nfunction filtered(){\n  const q = state.q.trim().toLowerCase();\n  if (!q) return state.mails;\n  return state.mails.filter(m =>\n    (m.subject||'').toLowerCase().includes(q) ||\n    prettySender(m.sender||'').toLowerCase().includes(q) ||\n    (m.body||'').toLowerCase().includes(q));\n}\nasync function loadInbox(){\n  const sc = $('#list-scroll');\n  sc.innerHTML = '<div class=\"spin\"></div>';\n  try {\n    if (!state.active){ sc.innerHTML = `<div class=\"empty\"><div class=\"ico\">📬</div><h3>No address</h3><p>Create an inbox from the sidebar.</p></div>`; return; }\n    const d = await api('/inbox?addr=' + encodeURIComponent(state.active));\n    state.mails = d.mails || [];\n    renderList();\n  } catch (e){\n    sc.innerHTML = `<div class=\"empty\"><div class=\"ico\">⚠️</div><p>${esc(e.message)}</p></div>`;\n  }\n}\nfunction renderList(){\n  const sc = $('#list-scroll');\n  const items = filtered();\n  $('#tb-title').textContent = state.active || 'Inbox';\n  if (!items.length){\n    sc.innerHTML = state.q\n      ? `<div class=\"empty\"><div class=\"ico\">🔍</div><h3>No matches</h3><p>Nothing matches “${esc(state.q)}”.</p></div>`\n      : `<div class=\"empty\"><div class=\"ico\">📭</div><h3>Inbox is empty</h3><p>Emails to <b>${esc(state.active||'')}</b> will appear here instantly.</p></div>`;\n    return;\n  }\n  sc.innerHTML = items.map((m, i) => {\n    const otp = extractOtp(m.body);\n    return `<div class=\"mail ${m.read?'':'unread'} ${i===state.openIdx?'on':''}\" data-i=\"${i}\">\n      ${m.read?'':'<span class=\"unread-dot\"></span>'}\n      <div class=\"avatar\" style=\"background:${avatarColor(m.sender)}\">${esc(initials(prettySender(m.sender)))}</div>\n      <div class=\"who\">\n        <div class=\"r1\"><span class=\"sender\">${esc(prettySender(m.sender))}</span><span class=\"time\">${fmtTime(m.received_at)}</span></div>\n        <div class=\"subj\">${esc(m.subject || '(no subject)')}</div>\n        <div class=\"preview\">${esc((m.body||'').replace(/\\s+/g,' ').slice(0,140))}</div>\n        ${otp?`<span class=\"otp-chip\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></svg>${esc(otp)}</span>`:''}\n      </div>\n    </div>`;\n  }).join('');\n  sc.querySelectorAll('.mail').forEach(el => el.addEventListener('click', () => openMail(+el.dataset.i)));\n}\n\n/* ==================== READER ==================== */\nfunction renderBody(text){\n  if (!text) return '<span style=\"color:var(--faint)\">(no content)</span>';\n  let t = esc(text);\n  t = t.replace(/(https?:\\/\\/[^\\s<>\"']+|mailto:[^\\s<>\"']+)/g, m => `<a href=\"${esc(m)}\" target=\"_blank\" rel=\"noopener\">${esc(m)}</a>`);\n  return t;\n}\nfunction openMail(i){\n  const items = filtered();\n  const m = items[i];\n  if (!m) return;\n  state.openIdx = i;\n  document.body.classList.add('reader-open');\n  $('#r-subj').textContent = m.subject || '(no subject)';\n  $('#r-meta').innerHTML = `<div class=\"from-line\">\n      <div class=\"avatar\" style=\"background:${avatarColor(m.sender)}\">${esc(initials(prettySender(m.sender)))}</div>\n      <div><b>${esc(prettySender(m.sender))}</b><br><span style=\"font-size:11.5px;color:var(--faint)\">${esc((m.sender||'').replace(/^.*<([^>]*)>.*$/,'$1'))}</span></div>\n    </div>\n    <div>To <b dir=\"ltr\">${esc(m.address)}</b></div>\n    <div style=\"margin-top:2px\">${fmtFull(m.received_at)}</div>`;\n  const body = $('#reader-body');\n  const otp = extractOtp(m.body);\n  body.innerHTML = otp\n    ? `<div class=\"otp-big\"><code>${esc(otp)}</code>\n        <button class=\"btn ghost sm\" id=\"otp-copy\">Copy</button></div>` + renderBody(m.body)\n    : renderBody(m.body);\n  const oc = $('#otp-copy');\n  if (oc) oc.addEventListener('click', () => copy(otp, 'Code copied'));\n  maybeRenderHtml(m);\n  renderList();\n  $('#reader-scroll').scrollTop = 0;\n  if (!m.read) markRead(m);\n}\nfunction maybeRenderHtml(m){\n  if (!m.html_snippet) return;\n  try {\n    const body = $('#reader-body');\n    const snip = m.html_snippet.trim();\n    if (snip.length < 30) return;\n    const frame = document.createElement('iframe');\n    frame.className = 'html-mail';\n    frame.sandbox = 'allow-same-origin allow-popups';\n    const WRAP = `<!DOCTYPE html><html dir=\"ltr\"><head><meta charset=\"UTF-8\">\n      <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n      <style>\n        html,body{margin:0;padding:0}\n        body{font-family:-apple-system,Segoe UI,Tahoma,sans-serif;font-size:14px;color:#111;background:#fff}\n        body>*{padding:12px}\n        img{max-width:100%!important;height:auto!important}\n        a{color:#2b6cb0;word-break:break-all}\n        table{max-width:100%!important}\n        *{box-sizing:border-box}\n      </style></head><body>`;\n    const isFullDoc = /^<!DOCTYPE|<html[\\s>]/i.test(snip);\n    if (isFullDoc){\n      const bm = snip.match(/<body[\\s\\S]*<\\/body>/i);\n      frame.srcdoc = WRAP + (bm ? bm[0].replace(/<\\/?body[^>]*>/gi, '') : snip) + '</body></html>';\n    } else {\n      frame.srcdoc = WRAP + snip + '</body></html>';\n    }\n    const plain = body.querySelector('.plain-fallback');\n    // wrapper برای اسکرول افقی ایمیل‌های پهن (عرض ثابت ۶۰۰px)\n    const wrap = document.createElement('div');\n    wrap.style.cssText = 'overflow-x:auto;-webkit-overflow-scrolling:touch;border-radius:10px';\n    wrap.appendChild(frame);\n    body.appendChild(wrap);\n    frame.style.display = 'none';\n    const resize = () => {\n      try {\n        const doc = frame.contentDocument;\n        if (!doc) return;\n        // عرض کانتینر — iframe نباید از صفحه بیرون بزنه\n        const w = wrap.clientWidth;\n        if (w > 0) frame.style.width = w + 'px';\n        const h = Math.max(doc.documentElement.scrollHeight, doc.body ? doc.body.scrollHeight : 0);\n        frame.style.height = Math.max(h + 16, 100) + 'px';\n      } catch {}\n    };\n    frame.addEventListener('load', () => {\n      try {\n        const doc = frame.contentDocument;\n        const txt = doc ? (doc.body && doc.body.innerText || '').trim() : '';\n        if (!txt && !doc.querySelector('img, video')){ frame.remove(); return; }\n        if (plain) plain.remove();\n        frame.style.display = '';\n        doc.querySelectorAll('img').forEach(img => {\n          img.addEventListener('load', resize, { once: true });\n          img.addEventListener('error', resize, { once: true });\n        });\n      } catch { try { if (plain) plain.remove(); frame.style.display = ''; } catch {} }\n      resize();\n      setTimeout(resize, 300);\n      setTimeout(resize, 900);\n    });\n  } catch {}\n}\nasync function markRead(m){\n  m.read = 1;\n  try { await api('/read/' + m.id, { method: 'POST' }); } catch {}\n}\nfunction navMail(delta){\n  const items = filtered();\n  const n = state.openIdx + delta;\n  if (n >= 0 && n < items.length) openMail(n);\n}\nasync function deleteMail(){\n  const items = filtered();\n  const m = items[state.openIdx];\n  if (!m) return;\n  try {\n    await api('/mail/' + m.id, { method: 'DELETE' });\n    state.mails = state.mails.filter(x => x.id !== m.id);\n    state.openIdx = -1;\n    document.body.classList.remove('reader-open');\n    $('#reader-body').innerHTML = '<div class=\"empty\"><div class=\"ico\">🗑️</div><p>Email deleted.</p></div>';\n    renderList();\n    toast('Deleted');\n  } catch (e){ toast(e.message); }\n}\n\n/* ==================== NEW ADDRESS SHEET ==================== */\nfunction newAddress(){\n  const name = prompt('Choose a name for your new address (leave empty for random):');\n  if (name === null) return;\n  api('/address', { method: 'POST', body: JSON.stringify({ name: name.trim(), domain: state.domain }) })\n    .then(d => { toast('Address created'); state.active = d.address; loadAddresses().then(loadInbox); })\n    .catch(e => toast(e.message));\n}\n\n/* ==================== SIDEBAR (mobile) ==================== */\nfunction openSide(){ document.body.classList.add('side-open'); }\nfunction closeSide(){ document.body.classList.remove('side-open'); }\n\n/* ==================== BOOT ==================== */\n$('#btn-refresh').addEventListener('click', () => { loadInbox(); toast('Synced'); });\n$('#btn-side').addEventListener('click', openSide);\n$('#btn-side-d').addEventListener('click', openSide);\n$('#btn-new').addEventListener('click', newAddress);\n$('#btn-new-m').addEventListener('click', newAddress);\n$('#btn-back').addEventListener('click', () => { document.body.classList.remove('reader-open'); state.openIdx = -1; renderList(); });\n$('#btn-prev').addEventListener('click', () => navMail(-1));\n$('#btn-next').addEventListener('click', () => navMail(1));\n$('#btn-del').addEventListener('click', deleteMail);\n$('#btn-logout').addEventListener('click', () => {\n  api('/logout', { method: 'POST' }).then(() => location.href = '/web').catch(() => location.href = '/web');\n});\n$('#side-scrim').addEventListener('click', closeSide);\nlet sT;\n$('#search').addEventListener('input', e => { state.q = e.target.value; clearTimeout(sT); sT = setTimeout(renderList, 140); });\n\n(async function boot(){\n  try {\n    const meta = await api('/meta');\n    state.domain = meta.domain || state.domain;\n    state.user = meta.user || state.user;\n  } catch {}\n  await loadAddresses();\n  await loadInbox();\n  // refresh inbox when tab becomes visible again\n  document.addEventListener('visibilitychange', () => { if (!document.hidden && state.active) loadInbox(); });\n})();\n</script>\n</body>\n</html>\n";
